<?php requireLogin(); require 'includes/functions.php'; if(!db()){flash('error','Database unavailable.');header('Location:checkout.php');exit;} $items=[];$total=0;foreach(cart() as $code=>$qty){$p=productByCode($code);if(!$p||$qty>$p['stock']){flash('error','Stock unavailable for one or more products.');header('Location:cart.php');exit;}$total+=$p['price']*$qty;$items[]=[$p,$qty];}$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO orders(customer_id,customer_name,phone,address,payment_method,total,status) VALUES(?,?,?,?,?,?,?)');$s->execute([$_SESSION['customer_id'],$_POST['name'],$_POST['phone'],$_POST['address'],$_POST['payment'],$total,'Placed']);$oid=$pdo->lastInsertId();$it=$pdo->prepare('INSERT INTO order_items(order_id,product_code,product_name,qty,price,subtotal) VALUES(?,?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE code=?');foreach($items as [$p,$q]){$it->execute([$oid,$p['code'],$p['name'],$q,$p['price'],$p['price']*$q]);$up->execute([$q,$p['code']]);}$pdo->commit();clearCart();header('Location:order.php?id='.$oid);exit;}catch(Throwable $e){$pdo->rollBack();flash('error','Order could not be placed.');header('Location:checkout.php');}
